      "evidence": [
        {"source": "schematic", "quote": "CAN bus page: U11 value 'DIO'; U10 value 'DIO'."},
        {"source": "spec", "quote": "isolated CAN transceiver (U11/companion)"}
      ],
      "impact": "BOM will be wrong; assembler may place a digital isolator or wrong part, preventing CAN communication.",
      "confidence": 0.8
    }
  ],
  "summary": "Two significant anomalies found: the +12V boost feedback divider is set for ~6V not 12V, and the isolated CAN transceivers have their isolation grounds tied together and are powered from the non-isolated 5V rail, defeating isolation."
